from pathlib import Path
from types import SimpleNamespace
import hashlib
import json

source_path = Path('/private/tmp/opc-core-de3vsjla/baseline/C08/project/agent.py')
source = source_path.read_bytes()
namespace = {}
exec(compile(source, str(source_path), 'exec'), namespace)
execute = namespace['execute']

class CrashBeforeCheckpoint(Exception):
    pass

class External:
    def __init__(self):
        self.records = []
    def create(self, payload):
        result = {'id': 101 + len(self.records), 'payload': payload}
        self.records.append(result)
        return result

class Checkpoints:
    def __init__(self, crash_once=False):
        self.completed = {}
        self.crash_once = crash_once
    def done(self, action_id):
        return action_id in self.completed
    def complete(self, action_id, result):
        if self.crash_once:
            self.crash_once = False
            raise CrashBeforeCheckpoint('injected before checkpoint persistence')
        self.completed[action_id] = result

action = SimpleNamespace(id='a1', payload={'title': 'fixture'})
results = []
for scenario, crash in [('normal_then_replay', False), ('create_then_crash_then_resume', True)]:
    external = External()
    checkpoints = Checkpoints(crash_once=crash)
    try:
        execute(action, external, checkpoints)
    except CrashBeforeCheckpoint:
        assert len(external.records) == 1 and not checkpoints.done(action.id)
    execute(action, external, checkpoints)
    expected = 2 if crash else 1
    assert len(external.records) == expected
    assert checkpoints.done(action.id)
    results.append({'scenario': scenario, 'create_calls': len(external.records), 'record_ids': [r['id'] for r in external.records], 'checkpoint_record_id': checkpoints.completed[action.id]['id']})
